def build_sft_sample(prompt_ids, answer_ids, eos_id):
    full_answer = list(answer_ids) + [eos_id]
    input_ids = list(prompt_ids) + full_answer
    labels = [-100] * len(prompt_ids) + full_answer
    return {"input_ids": input_ids, "labels": labels}

def pad_batch(batch, pad_id=0):
    L = max(len(b["input_ids"]) for b in batch)
    ids, labels, mask = [], [], []
    for b in batch:
        n = len(b["input_ids"])
        pad = L - n
        ids.append(list(b["input_ids"]) + [pad_id] * pad)
        labels.append(list(b["labels"]) + [-100] * pad)
        mask.append([1] * n + [0] * pad)
    return {"input_ids": ids, "labels": labels, "attention_mask": mask}
